#!/usr/bin/env python3
"""Generate slab boundary-layer physics Metal arithmetic from authoritative GLSL."""
import argparse
from generate_tke_msl import ROOT, translate


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "metal/include/compute/metal/shaders/boundary_layer/slab_column_msl.hpp"
    source = translate("slab_column", "boundary_layer").replace(
        "Generated by scripts/dev/shaders/generate_tke_msl.py",
        "Generated by scripts/dev/shaders/generate_slab_column_msl.py",
    )
    if args.check:
        if not path.exists() or path.read_text() != source:
            raise SystemExit("slab-column Metal source is stale")
    else:
        path.write_text(source)


if __name__ == "__main__":
    main()
